insert into public.insight_rules (id, category, severity, priority, conditions, title, body, headline, reason, action, slot) values
  ('health_illness_pattern', 'health', 'warn', 96, '[{"m":"rhr_z","op":"gte","v":1.5},{"m":"rr_z","op":"gte","v":1.5}]'::jsonb, 'Possible illness brewing', 'Resting heart rate and breathing rate are both well above your normal — the classic early pattern of a cold, infection or overreaching. Make today a rest day, drink plenty, and see how tomorrow''s numbers look before training hard.', 'Possible illness brewing', 'with resting HR and breathing rate both up', 'Make today a rest day and drink plenty', 'app'),
  ('health_illness_glucose', 'health', 'warn', 97, '[{"m":"rhr_z","op":"gte","v":1.5},{"m":"dx_mean_24h","op":"gte","v":10}]'::jsonb, 'Raised heart rate and higher glucose', 'Resting HR is up and glucose has averaged {dx_mean_24h:1} mmol/L over 24h — together that often means illness. Follow your sick-day rules: keep basal insulin going, check ketones if you''re running high, drink plenty, and rest.', 'Resting HR and glucose both up', 'with glucose averaging {dx_mean_24h:1} over 24h', 'Follow your sick-day rules — keep basal going, check ketones if high', 'app'),
  ('health_temp_high', 'health', 'caution', 88, '[{"m":"wrist_temp","op":"gte","v":0.6}]'::jsonb, 'Wrist temperature up {wrist_temp:1}°C', 'A raised overnight temperature is often the first sign of illness — it can also follow alcohol, a late heavy meal or a hot room. Keep training easy today and watch for symptoms.', 'Wrist temperature up {wrist_temp:1}°C', 'with wrist temperature up {wrist_temp:1}°C', 'Keep training easy and watch for symptoms', 'app'),
  ('glucose_low_now', 'glucose', 'warn', 100, '[{"m":"dx_bg","op":"lt","v":3.9},{"m":"dx_bg_age_min","op":"lte","v":15}]'::jsonb, 'Low: {dx_bg:1} mmol/L', 'Treat it now per your hypo plan (typically 15g fast-acting carbs) and recheck in 15 minutes. Don''t exercise until you''re back above 5.', 'Low: {dx_bg:1} mmol/L', null, 'Treat it now per your hypo plan and recheck in 15 min', 'app'),
  ('glucose_dropping', 'glucose', 'warn', 98, '[{"m":"dx_bg","op":"between","v":[3.9,5.5]},{"m":"dx_trend5","op":"lte","v":-0.3},{"m":"dx_bg_age_min","op":"lte","v":15}]'::jsonb, 'Dropping: {dx_bg:1} and falling', 'Falling {dx_trend5:1} mmol/L every 5 minutes. Have fast carbs to hand and check the forecast on the Diabetes tab.', 'Glucose dropping ({dx_bg:1})', null, 'Have fast carbs to hand', 'app'),
  ('glucose_high_now', 'glucose', 'caution', 90, '[{"m":"dx_bg","op":"gte","v":13.9},{"m":"dx_bg_age_min","op":"lte","v":15}]'::jsonb, 'High: {dx_bg:1} mmol/L', 'Drink water and check the correction card on the Diabetes tab. If it''s been high for a couple of hours or you feel unwell, check ketones.', 'High: {dx_bg:1} mmol/L', null, 'Drink water and check the Diabetes tab', 'app'),
  ('glucose_low_iob_before_exercise', 'glucose', 'caution', 72, '[{"m":"dx_bg","op":"lt","v":6.5},{"m":"dx_iob","op":"gte","v":1.5},{"m":"dx_bg_age_min","op":"lte","v":15},{"m":"hour","op":"between","v":[6,20]}]'::jsonb, 'Training soon? Check first', 'Glucose {dx_bg:1} with {dx_iob:1}u of insulin still active — exercise now could pull you low. Use the pre-workout advisor on the Diabetes tab before you start.', null, 'with {dx_iob:1}u active and glucose {dx_bg:1}', 'Check the pre-workout advisor before training', 'app'),
  ('glucose_stale', 'glucose', 'info', 58, '[{"m":"dx_bg_age_min","op":"between","v":[30,720]}]'::jsonb, 'No glucose reading for {dx_bg_age_min} min', 'Check your sensor and the Nightscout uploader — the forecast and alerts can''t help while readings are missing.', null, 'no glucose reading for {dx_bg_age_min} min', 'Check your sensor and uploader', 'app'),
  ('diabetes_vlow_week', 'diabetes', 'warn', 87, '[{"m":"dx_vlow_7d","op":"gt","v":1}]'::jsonb, '{dx_vlow_7d:1}% of the week under 3.0', 'The consensus target is under 1% below 3.0 mmol/L. Check Patterns on the Diabetes tab for when they happen — repeated serious lows are worth raising with your diabetes team.', null, '{dx_vlow_7d:1}% of the week under 3.0', 'Check Patterns on the Diabetes tab', 'app'),
  ('diabetes_hypos_24h', 'diabetes', 'warn', 86, '[{"m":"dx_hypos_24h","op":"gte","v":2}]'::jsonb, '{dx_hypos_24h} lows in the last 24 hours', 'More than one low in a day usually has a common cause — a meal ratio or basal rate that''s too strong, or extra activity. Look at the Diabetes tab''s Patterns before your next similar meal or session.', null, 'after {dx_hypos_24h} lows in 24h', 'Check Patterns before your next similar meal or session', 'app'),
  ('diabetes_night_low', 'diabetes', 'caution', 84, '[{"m":"dx_night_low","op":"lt","v":3.9}]'::jsonb, 'Low overnight (down to {dx_night_low:1})', 'Night-time lows disturb sleep and often show up as a poor sleep score and low Body Battery. Late exercise and evening corrections are common causes — check the overnight part of Patterns.', null, 'after a low overnight (down to {dx_night_low:1})', 'Check the overnight part of Patterns', 'app'),
  ('diabetes_tbr_high', 'diabetes', 'warn', 82, '[{"m":"dx_below_7d","op":"gt","v":4}]'::jsonb, 'Time below range {dx_below_7d:1}% this week', 'The target is under 4% below 3.9 mmol/L. Reducing lows comes before chasing time in range — the Diabetes tab''s regimen review shows which time of day needs attention.', null, 'time below range {dx_below_7d:1}% this week', null, 'app'),
  ('diabetes_lows_training', 'diabetes', 'caution', 70, '[{"m":"dx_below_7d","op":"gt","v":3},{"m":"workouts_7d","op":"gte","v":4}]'::jsonb, 'Lows alongside lots of training', 'Exercise raises insulin sensitivity for up to 24-48 hours, so busy training weeks often bring more lows — especially overnight. The workout profiles on the Diabetes tab show how each session type affects you.', null, 'with lows alongside lots of training', null, 'app'),
  ('diabetes_night_high', 'diabetes', 'caution', 66, '[{"m":"dx_night_mean","op":"gte","v":10}]'::jsonb, 'High overnight (average {dx_night_mean:1})', 'Common causes: a late or high-fat/protein meal (slow, delayed rise), a missed bolus, or basal that''s too light overnight. If it repeats, check the overnight window in Patterns.', null, 'after running high overnight (avg {dx_night_mean:1})', null, 'app'),
  ('diabetes_tir_low', 'diabetes', 'caution', 64, '[{"m":"dx_tir_7d","op":"lt","v":70}]'::jsonb, 'Time in range {dx_tir_7d}% this week', 'Target is 70%+ in 3.9-10 mmol/L. {dx_above_7d}% was above range — Patterns on the Diabetes tab shows which meals or times of day push you high.', null, 'time in range {dx_tir_7d}% this week', null, 'app'),
  ('diabetes_tir_worse', 'diabetes', 'caution', 62, '[{"m":"dx_tir_delta","op":"lte","v":-7}]'::jsonb, 'Time in range down {dx_tir_delta} points', 'Down on last week. Illness, stress, less activity or a change in eating are the usual causes — worth a look at the weekly health check on the Diabetes tab.', null, 'time in range down on last week', null, 'app'),
  ('diabetes_cv_high', 'diabetes', 'caution', 60, '[{"m":"dx_cv_7d","op":"gt","v":36}]'::jsonb, 'Glucose swings: variability {dx_cv_7d}%', 'Above the 36% target — big swings, not just the average, drive lows and how you feel. Pre-bolusing 10-15 min before carbs and splitting doses for high-fat meals are the usual fixes.', null, 'glucose variability {dx_cv_7d}%', null, 'app'),
  ('diabetes_sensor_patchy', 'diabetes', 'info', 55, '[{"m":"dx_coverage_24h","op":"lt","v":70}]'::jsonb, 'Sensor data patchy ({dx_coverage_24h}% of readings)', 'Gaps make the stats and forecasts less reliable. Check the sensor, phone Bluetooth and the uploader.', null, 'sensor data patchy ({dx_coverage_24h}%)', null, 'app'),
  ('diabetes_tir_improving', 'diabetes', 'good', 36, '[{"m":"dx_tir_delta","op":"gte","v":5}]'::jsonb, 'Time in range up {dx_tir_delta} points', 'Better than last week — whatever changed is working. {dx_tir_7d}% in range now.', null, 'time in range up {dx_tir_delta} points', null, 'app'),
  ('diabetes_tir_great', 'diabetes', 'good', 32, '[{"m":"dx_tir_7d","op":"gte","v":80},{"m":"dx_below_7d","op":"lt","v":4}]'::jsonb, 'Excellent week: {dx_tir_7d}% in range', 'Above the 70% target with lows under control. Estimated HbA1c (GMI) about {dx_gmi:1}%.', null, '{dx_tir_7d}% in range this week', null, 'app'),
  ('diabetes_day_great', 'diabetes', 'good', 26, '[{"m":"dx_tir_24h","op":"gte","v":85},{"m":"dx_below_24h","op":"lt","v":2}]'::jsonb, '{dx_tir_24h}% in range over 24h', 'A really steady day.', null, '{dx_tir_24h}% in range over 24h', null, 'app'),
  ('diabetes_gmi', 'diabetes', 'info', 8, '[{"m":"dx_gmi","op":"exists","v":true}]'::jsonb, 'Estimated HbA1c about {dx_gmi:1}%', 'GMI from your last 7 days of CGM (average {dx_mean_7d:1} mmol/L). Time in range {dx_tir_7d}%.', null, 'estimated HbA1c {dx_gmi:1}%', null, 'app'),
  ('recovery_red', 'recovery', 'warn', 80, '[{"m":"recovery","op":"lt","v":34}]'::jsonb, 'Recovery {recovery} — take it easy', 'Well below your normal. Rest or active recovery only: a walk, mobility, an easy spin. Keep strain under 8 and get to bed early.', 'Recovery {recovery}', null, 'Take it easy — light walk today', 'morning'),
  ('recovery_tired_despite_green', 'recovery', 'info', 71, '[{"m":"recovery","op":"gte","v":67},{"m":"feel","op":"lte","v":2}]'::jsonb, 'Numbers say go, you say no', 'Recovery is {recovery} but you feel rough. Trust the feeling today — keep it moderate. Your check-ins teach Recovery what matters for you.', 'Recovery {recovery}, but you felt rough', null, 'Keep it moderate today', 'morning'),
  ('recovery_fresh_despite_red', 'recovery', 'info', 69, '[{"m":"recovery","op":"lt","v":40},{"m":"feel","op":"gte","v":4}]'::jsonb, 'You feel better than your numbers', 'Recovery {recovery} but you feel good. A moderate session is reasonable — stop early if heart rate runs higher than usual for the effort.', 'Recovery {recovery}, but you feel good', null, 'A moderate session is fine — stop early if your heart rate runs high', 'morning'),
  ('recovery_below', 'recovery', 'caution', 60, '[{"m":"recovery","op":"between","v":[34,49]}]'::jsonb, 'Recovery {recovery} — go lighter', 'Below your normal. Train, but cap the intensity: technique work, fewer hard sets, strain {strain_target_lo:1}-{strain_target_hi:1}.', 'Recovery {recovery}', 'and Recovery''s only {recovery}', 'Train, but go lighter — technique work, fewer hard sets', 'morning'),
  ('recovery_green', 'recovery', 'good', 40, '[{"m":"recovery","op":"gte","v":67}]'::jsonb, 'Green light — Recovery {recovery}', 'Well recovered. A good day for your hardest session or a PB attempt — strain target {strain_target_lo:1}-{strain_target_hi:1}.', 'You''ve recovered well ({recovery})', null, 'Push hard today', 'morning'),
  ('recovery_normal', 'recovery', 'info', 30, '[{"m":"recovery","op":"between","v":[50,66]}]'::jsonb, 'Recovery {recovery} — train as planned', 'Around your normal. Stick to the plan; strain target {strain_target_lo:1}-{strain_target_hi:1}.', 'Recovery {recovery}, about your normal', null, 'Train as planned — strain {strain_target_lo:1}-{strain_target_hi:1}', 'morning'),
  ('trend_hrv_down', 'trend', 'caution', 76, '[{"m":"hrv_trend_7","op":"lte","v":-0.75}]'::jsonb, 'HRV down all week', 'Your 7-day HRV average is well below your normal — the most reliable sign of accumulated fatigue. Plan a deload or two easy days, and protect sleep.', null, 'HRV''s been down all week', 'Plan a deload or two easy days', 'morning'),
  ('trend_short_nights', 'trend', 'warn', 73, '[{"m":"short_nights_7","op":"gte","v":4}]'::jsonb, '{short_nights_7} short nights this week', 'Four or more nights under 6 hours affects recovery, appetite, mood and glucose control more than any single bad night. Pick a fixed bedtime for the next 3 nights.', null, '{short_nights_7} short nights this week', 'Pick a fixed bedtime for the next 3 nights', 'both'),
  ('trend_rhr_up', 'trend', 'caution', 70, '[{"m":"rhr_trend_7","op":"gte","v":1}]'::jsonb, 'Resting heart rate creeping up', 'Up on your normal all week. Common causes: hard training without enough rest, poor sleep, alcohol, stress or an illness coming on. Ease off for a couple of days.', null, 'resting HR''s been creeping up', 'Ease off for a couple of days', 'morning'),
  ('trend_hrv_up', 'trend', 'good', 34, '[{"m":"hrv_trend_7","op":"gte","v":0.75}]'::jsonb, 'HRV trending up', 'Your 7-day HRV average is above your normal — you''re adapting well to your training. A good week to progress.', null, 'HRV''s trending up', null, 'morning'),
  ('sleep_very_short', 'sleep', 'warn', 78, '[{"m":"sleep_hrs","op":"lt","v":5}]'::jsonb, 'Only {sleep_hrs:1}h sleep', 'Reaction time, appetite control and glucose all suffer after a night under 5 hours. Skip max-effort lifts, get daylight early, keep caffeine before noon, and aim for {sleep_need:1}h tonight.', 'Only {sleep_hrs:1}h sleep', 'after only {sleep_hrs:1}h sleep', 'Skip max-effort lifts and aim for {sleep_need:1}h tonight', 'morning'),
  ('sleep_debt_high', 'sleep', 'caution', 58, '[{"m":"sleep_debt","op":"gte","v":1.2}]'::jsonb, 'Sleep debt building ({sleep_debt:1}h)', 'Going to bed 30-45 minutes earlier for three nights clears most of it — more effective than one long lie-in.', null, 'with {sleep_debt:1}h of sleep debt', 'Go to bed 30-45 min earlier for three nights', 'both'),
  ('sleep_poor_with_highs', 'sleep', 'info', 57, '[{"m":"dx_night_mean","op":"gte","v":10},{"m":"sleep_score","op":"lt","v":60}]'::jsonb, 'High glucose and poor sleep', 'Running high overnight (average {dx_night_mean:1}) disturbs sleep, and poor sleep raises insulin resistance the next day. Fixing the overnight highs often improves both.', null, 'after a night running high', null, 'morning'),
  ('sleep_short', 'sleep', 'caution', 55, '[{"m":"sleep_hrs","op":"between","v":[5,6.5]}]'::jsonb, 'Short night: {sleep_hrs:1}h', 'Below what you need. Keep today''s training moderate and aim for {sleep_need:1}h tonight.', 'Short night: {sleep_hrs:1}h', 'after a short {sleep_hrs:1}h night', 'Keep training moderate today', 'morning'),
  ('sleep_target_met', 'sleep', 'good', 24, '[{"m":"sleep_perf","op":"gte","v":95}]'::jsonb, 'Sleep target met', '{sleep_hrs:1}h — {sleep_perf}% of what you needed. Nights like this are what make the rest of the plan work.', null, 'after {sleep_hrs:1}h of solid sleep', null, 'morning'),
  ('battery_empty', 'battery', 'warn', 92, '[{"m":"battery","op":"lte","v":15}]'::jsonb, 'Body Battery {battery}% — empty', 'Running on fumes. Drop anything optional, no hard training, eat a proper meal and make tonight an early night.', null, 'Body Battery is at {battery}%', 'No hard training — make it an early night', 'evening'),
  ('battery_very_low', 'battery', 'warn', 74, '[{"m":"battery","op":"between","v":[16,25]}]'::jsonb, 'Body Battery {battery}% — very low', 'Keep the rest of the day light: a short walk outside, a proper meal, screens down early. Anything hard now will cost you tomorrow.', null, 'Body Battery {battery}%', 'Keep the rest of the evening light', 'evening'),
  ('battery_poor_charge', 'battery', 'caution', 64, '[{"m":"battery_charged","op":"lt","v":25},{"m":"hour","op":"lt","v":12}]'::jsonb, 'Only charged +{battery_charged}% overnight', 'A weak recharge usually comes from short sleep, alcohol, a late heavy meal, hard training close to bed, or a night low. Woke on {battery_wake}%.', null, 'with only +{battery_charged}% recharge overnight', null, 'morning'),
  ('battery_woke_low', 'battery', 'caution', 62, '[{"m":"battery_wake","op":"lt","v":50},{"m":"hour","op":"lt","v":12}]'::jsonb, 'Woke on {battery_wake}%', 'You didn''t recharge fully. Plan a lighter day and protect tonight''s sleep.', null, 'on {battery_wake}% Body Battery', 'Plan a lighter day', 'morning'),
  ('battery_stress_drain', 'battery', 'caution', 58, '[{"m":"battery_stress_drain","op":"gte","v":20},{"m":"battery_ex_drain","op":"lt","v":10}]'::jsonb, 'Stress, not training, is draining you', '−{battery_stress_drain}% today from raised heart rate while not exercising. Short walks, a 5-minute slow-breathing break (about 6 breaths a minute) and caffeine before noon only help most.', null, null, null, 'app'),
  ('battery_fast_drain', 'battery', 'caution', 56, '[{"m":"battery_rate","op":"lte","v":-6}]'::jsonb, 'Draining fast ({battery_rate:1}%/hr)', 'Stress or activity is high right now. If you''re not training, a few minutes of slow breathing is the quickest way to bring it down.', null, null, null, 'app'),
  ('battery_runs_out', 'battery', 'caution', 54, '[{"m":"battery_low_hour","op":"between","v":[8,20]},{"m":"hour","op":"between","v":[7,18]}]'::jsonb, 'On course for 25% by about {battery_low_hour}:00', 'At this rate you''ll be very low by early evening. Pace the afternoon: a calm break or a short walk outside slows the drain.', null, null, null, 'app'),
  ('battery_low_for_training', 'battery', 'caution', 52, '[{"m":"battery","op":"between","v":[26,35]},{"m":"hour","op":"lt","v":18}]'::jsonb, 'Low battery for a workout ({battery}%)', 'If you train today, keep it short and easy — 20-30 minutes of easy cardio or technique work rather than heavy lifting.', null, null, null, 'app'),
  ('battery_evening_low', 'battery', 'info', 50, '[{"m":"hour","op":"gte","v":19},{"m":"battery","op":"between","v":[26,30]}]'::jsonb, 'Wind down early ({battery}%)', 'Dim lights, screens off 30 minutes before bed, and aim for {sleep_need:1}h — a good night is the only real recharge.', null, 'Body Battery {battery}%', 'Wind down early — screens off 30 min before bed', 'evening'),
  ('battery_high_recovery_low', 'battery', 'info', 40, '[{"m":"battery","op":"gte","v":70},{"m":"recovery","op":"lt","v":40}]'::jsonb, 'Charged up, but Recovery is low', 'Body Battery {battery}% but Recovery {recovery}. Energy for the day is fine; the low Recovery says your body is still absorbing recent training — avoid max efforts.', null, null, null, 'app'),
  ('battery_full_morning', 'battery', 'good', 34, '[{"m":"battery_wake","op":"gte","v":80},{"m":"hour","op":"lt","v":12}]'::jsonb, 'Woke on {battery_wake}%', 'Fully recharged (+{battery_charged}% overnight). A great day for your hardest session.', null, 'with Body Battery at {battery_wake}%', null, 'morning'),
  ('battery_great_charge', 'battery', 'good', 30, '[{"m":"battery_charged","op":"gte","v":50}]'::jsonb, 'Great recharge: +{battery_charged}%', 'A strong night — whatever you did yesterday evening, repeat it.', null, 'after a +{battery_charged}% recharge', null, 'morning'),
  ('battery_ready_to_train', 'battery', 'good', 26, '[{"m":"battery","op":"gte","v":60},{"m":"recovery","op":"gte","v":50},{"m":"hour","op":"lt","v":18}]'::jsonb, 'Plenty in the tank ({battery}%)', 'Body Battery and Recovery both support a proper session today.', null, null, null, 'app'),
  ('battery_evening_high', 'battery', 'info', 22, '[{"m":"hour","op":"gte","v":20},{"m":"battery","op":"gte","v":60}]'::jsonb, 'Still on {battery}% this evening', 'A quiet day. A short walk now builds sleep pressure — you''ll fall asleep faster.', null, 'still on {battery}% Body Battery', 'A short walk now helps you fall asleep', 'evening'),
  ('battery_recharging', 'battery', 'good', 20, '[{"m":"battery_rate","op":"gte","v":1},{"m":"hour","op":"between","v":[9,21]}]'::jsonb, 'Recharging (+{battery_rate:1}%/hr)', 'Calm rest is topping you up. Nice.', null, null, null, 'app'),
  ('strain_over_target_low_recovery', 'strain', 'caution', 65, '[{"m":"strain_over","op":"gt","v":0},{"m":"recovery","op":"lt","v":50}]'::jsonb, 'Past today''s strain target', 'Strain {strain:1} against a target of {strain_target_lo:1}-{strain_target_hi:1} on a low-recovery day. Stop here: refuel with protein and carbs and get to bed early.', null, 'strain {strain:1}, over target on a low-recovery day', 'Refuel with protein and carbs, then an early night', 'evening'),
  ('strain_yesterday_big', 'strain', 'info', 50, '[{"m":"strain_yday","op":"gte","v":16},{"m":"hour","op":"lt","v":14}]'::jsonb, 'Big day yesterday (strain {strain_yday:1})', 'Expect Recovery to dip. Prioritise protein (about 30-40g a meal), fluids and sleep today.', null, 'after a big day yesterday (strain {strain_yday:1})', 'Prioritise protein, fluids and sleep', 'morning'),
  ('strain_room_left', 'strain', 'info', 30, '[{"m":"hour","op":"gte","v":16},{"m":"recovery","op":"gte","v":67},{"m":"strain","op":"lt","v":9}]'::jsonb, 'Room left today', 'Green recovery but strain only {strain:1}. A 30-minute brisk walk or short session would use it well.', null, 'strain only {strain:1} on a green day', 'A 30-min brisk walk would use it well', 'evening'),
  ('training_overreaching', 'training', 'caution', 68, '[{"m":"workouts_7d","op":"gte","v":6},{"m":"hrv_trend_7","op":"lt","v":-0.3}]'::jsonb, '{workouts_7d} sessions in 7 days, HRV dipping', 'Training volume is outpacing recovery. Schedule a full rest day in the next two days.', null, '{workouts_7d} sessions in 7 days with HRV dipping', 'Take a full rest day in the next two days', 'morning'),
  ('training_break_ready', 'training', 'info', 45, '[{"m":"days_since_workout","op":"gte","v":4},{"m":"recovery","op":"gte","v":50}]'::jsonb, '{days_since_workout} days since your last workout', 'Recovery is good — a good day to get back in, even a short session keeps the habit going.', null, '{days_since_workout} days since your last workout', 'Get back in, even a short session', 'morning'),
  ('nutrition_under_evening', 'nutrition', 'caution', 55, '[{"m":"hour","op":"gte","v":19},{"m":"consumed_pct","op":"lt","v":60},{"m":"consumed","op":"gt","v":0}]'::jsonb, 'Only {consumed} of {eat_target} kcal so far', 'A very big deficit hurts sleep and recovery and makes tomorrow''s hunger worse. Have a protein-rich meal this evening.', null, 'only {consumed} of {eat_target} kcal eaten', 'Have a protein-rich meal this evening', 'evening'),
  ('nutrition_weekly_deficit_big', 'nutrition', 'caution', 52, '[{"m":"weekly_net","op":"lte","v":-5600},{"m":"weekly_days","op":"gte","v":5}]'::jsonb, 'Big deficit this week: {weekly_net_abs} kcal', 'About {weekly_kg:1}kg of fat — losing faster than roughly 1% of bodyweight a week risks muscle. Add 200-300 kcal on training days, mostly protein and carbs.', null, 'a {weekly_net_abs} kcal deficit this week', 'Add 200-300 kcal on training days', 'morning'),
  ('nutrition_weekly_surplus', 'nutrition', 'caution', 50, '[{"m":"weekly_net","op":"gte","v":1500},{"m":"has_plan","op":"eq","v":1},{"m":"weekly_days","op":"gte","v":5}]'::jsonb, 'Surplus this week: +{weekly_net} kcal', 'Eating more than you''ve burned over 7 days, which works against your weight plan. Logging every meal for the next few days is the quickest way to see where it''s coming from.', null, '+{weekly_net} kcal over the week', null, 'morning'),
  ('nutrition_over_today', 'nutrition', 'info', 45, '[{"m":"consumed_pct","op":"gte","v":115}]'::jsonb, '{over_kcal} kcal over today''s target', 'Fine now and then — it''s the weekly total that counts. Keep tomorrow at target.', null, '{over_kcal} kcal over target', null, 'evening'),
  ('nutrition_not_logged', 'nutrition', 'info', 40, '[{"m":"hour","op":"gte","v":14},{"m":"consumed","op":"exists","v":false},{"m":"food_logged_days_7","op":"gte","v":3}]'::jsonb, 'Nothing logged yet today', 'Log what you''ve eaten so far — same-day logging is far more accurate than remembering tonight.', null, null, null, 'app'),
  ('nutrition_weekly_on_track', 'nutrition', 'good', 20, '[{"m":"weekly_net","op":"between","v":[-5600,-2000]},{"m":"weekly_days","op":"gte","v":5}]'::jsonb, 'Steady deficit: {weekly_net_abs} kcal this week', 'About {weekly_kg:1}kg of fat a week — a sustainable pace that protects muscle.', null, 'a steady {weekly_net_abs} kcal deficit this week', null, 'morning'),
  ('weight_fast_loss', 'weight', 'caution', 48, '[{"m":"weight_change_14d","op":"lte","v":-2}]'::jsonb, 'Down {weight_change_14d:1}kg in two weeks', 'Faster than ideal for keeping muscle. Keep protein high (about 1.6-2g per kg) and keep lifting; consider eating a little more on training days.', null, 'weight dropping fast', 'Keep protein high and keep lifting', 'morning'),
